import React, { useState } from 'react';
import './NotepadWidget.css';

const NotepadWidget = ({ onClose }) => {
  const [notes, setNotes] = useState([
    { id: 1, title: 'Welcome', content: 'Welcome to Astra AI Notepad!', date: new Date().toLocaleDateString() }
  ]);
  const [selectedNote, setSelectedNote] = useState(1);
  const [editingTitle, setEditingTitle] = useState(false);
  const [editingContent, setEditingContent] = useState(false);

  const currentNote = notes.find(n => n.id === selectedNote);

  const handleCreateNote = () => {
    const newId = Math.max(...notes.map(n => n.id), 0) + 1;
    setNotes([...notes, {
      id: newId,
      title: 'New Note',
      content: '',
      date: new Date().toLocaleDateString()
    }]);
    setSelectedNote(newId);
  };

  const handleDeleteNote = () => {
    if (notes.length > 1) {
      const newNotes = notes.filter(n => n.id !== selectedNote);
      setNotes(newNotes);
      setSelectedNote(newNotes[0].id);
    }
  };

  const handleUpdateTitle = (newTitle) => {
    setNotes(notes.map(n => n.id === selectedNote ? { ...n, title: newTitle } : n));
  };

  const handleUpdateContent = (newContent) => {
    setNotes(notes.map(n => n.id === selectedNote ? { ...n, content: newContent } : n));
  };

  return (
    <div className="notepad-widget">
      <div className="corner-top-left"></div>
      <div className="corner-bottom-right"></div>
      
      <div className="notepad-header">
        <h2>Notepad</h2>
        <div className="notepad-actions">
          <button className="notepad-btn" onClick={handleCreateNote} title="New Note">
            <i className="fas fa-plus"></i>
          </button>
          <button className="notepad-btn delete-btn" onClick={handleDeleteNote} title="Delete Note">
            <i className="fas fa-trash"></i>
          </button>
        </div>
      </div>

      <div className="notepad-container">
        <div className="notes-list">
          {notes.map(note => (
            <div
              key={note.id}
              className={`note-item ${selectedNote === note.id ? 'active' : ''}`}
              onClick={() => setSelectedNote(note.id)}
            >
              <div className="note-title">{note.title}</div>
              <div className="note-date">{note.date}</div>
            </div>
          ))}
        </div>

        {currentNote && (
          <div className="notepad-editor">
            <div
              className="note-title-editor"
              onClick={() => setEditingTitle(true)}
              onBlur={() => setEditingTitle(false)}
            >
              {editingTitle ? (
                <input
                  type="text"
                  value={currentNote.title}
                  onChange={(e) => handleUpdateTitle(e.target.value)}
                  autoFocus
                  className="title-input"
                />
              ) : (
                <h3>{currentNote.title}</h3>
              )}
            </div>
            <textarea
              value={currentNote.content}
              onChange={(e) => handleUpdateContent(e.target.value)}
              placeholder="Start typing your note..."
              className="note-textarea"
            />
          </div>
        )}
      </div>
    </div>
  );
};

export default NotepadWidget;
